import pandas as pd

def find_zombie_sessions(sessions: pd.DataFrame) -> pd.DataFrame:
    if sessions.empty:
        return pd.DataFrame(columns=['session_id', 'user_id', 'start_time', 'end_time', 'activity_count'])

    start = pd.to_datetime(sessions['start_time'])
    end = pd.to_datetime(sessions['end_time'])
    diff_hours = (end - start).dt.total_seconds() / 3600.0

    cond = (sessions['activity_count'] == 0) | (diff_hours >= 24.0)
    res = sessions[cond].sort_values(by='session_id', ascending=True)
    return res[['session_id', 'user_id', 'start_time', 'end_time', 'activity_count']]
